-- ============================================================
-- KOMS — Database Schema
-- Generated by scaffold-schema on 2026-07-12
-- Source: PRD.md confirmed 2026-07-12
-- Every table traces to a screen in PRD.md's Screen Inventory.
-- ============================================================

-- ============================================================
-- ROOT ENTITY
-- ============================================================
-- Multi-tenant root. 1 row seeded for v1 (Gio's center, Indonesia).
-- Exists now so Singapore/other-country expansion never requires a schema rebuild.
create table centers (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  country text not null default 'Indonesia', -- 'Indonesia' | 'Singapore' | others as Kodecoon expands
  created_at timestamptz default now()
);

-- ============================================================
-- BUILD NOW — MVP (all P0, per the locked PRD)
-- ============================================================

-- Staff (teacher/center_manager/admin) AND parent accounts share this table.
-- id = auth.uid(), mirrors Supabase auth.users. Role-based, RLS-ready from day one
-- (same pattern as TCS Coffee's customer/admin/POS roles).
create table users (
  id uuid primary key references auth.users(id) on delete cascade,
  email text not null unique,
  name text not null,
  role text not null default 'teacher', -- 'teacher' | 'center_manager' | 'admin' | 'parent'
  center_id uuid references centers(id), -- null for parents, required for staff
  created_at timestamptz default now(),
  updated_at timestamptz default now(),
  -- Enforced, not just documented: several RLS policies scope by
  -- "center_id in (select center_id from users where id = auth.uid())".
  -- A parent with a non-null center_id would silently widen those policies to
  -- every student in the center, so the invariant has to be a constraint.
  constraint users_parent_has_no_center
    check (role <> 'parent' or center_id is null)
);

create table classes (
  id uuid primary key default gen_random_uuid(),
  center_id uuid not null references centers(id),
  teacher_id uuid not null references users(id),
  name text not null,           -- e.g. 'Scratch Junior', 'RCB', 'RGD Lv 2'
  age_bracket text,             -- e.g. '5-8', '8-12', '13-19'
  -- total lesson count is derived from COUNT(lessons) where class_id = this class,
  -- not stored here — avoids two sources of truth for curriculum size
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create table students (
  id uuid primary key default gen_random_uuid(),
  center_id uuid not null references centers(id),
  name text not null,
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create table enrollments (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references students(id) on delete cascade,
  class_id uuid not null references classes(id) on delete cascade,
  enrolled_date date not null default current_date,
  created_at timestamptz default now(),
  unique (student_id, class_id)
);

create table sessions (
  id uuid primary key default gen_random_uuid(),
  class_id uuid not null references classes(id),
  teacher_id uuid not null references users(id),
  session_date date not null,
  session_time time,            -- nullable; used by My Schedule
  status text not null default 'scheduled', -- 'scheduled' | 'completed'
  notes text,                   -- Gio's rough session notes; feeds the AI report draft
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);

create table attendance (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references sessions(id) on delete cascade,
  student_id uuid not null references students(id) on delete cascade,
  status text not null default 'unmarked', -- 'present' | 'absent' | 'unmarked'
  created_at timestamptz default now(),
  unique (session_id, student_id)
);

create table session_videos (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references sessions(id) on delete cascade,
  drive_file_id text not null,
  drive_link text not null,     -- shareable preview link — never raw video bytes in the DB
  created_at timestamptz default now(),
  unique (session_id, drive_file_id)
);

-- The lesson plan (curriculum template) for a class — e.g. 24 ordered lessons
-- for RCB. Admin-authored. This is what powers the snake-path journey view:
-- each row is one node on the path.
create table lessons (
  id uuid primary key default gen_random_uuid(),
  class_id uuid not null references classes(id) on delete cascade,
  sequence_number int not null, -- position on the journey path, 1-indexed
  title text not null,
  description text,
  created_at timestamptz default now(),
  unique (class_id, sequence_number)
);

-- Per-student completion state for each lesson node. This replaces the old
-- flat "credits" ledger — a completed lesson IS the credit, now named and
-- ordered instead of an anonymous count.
create table student_lesson_progress (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references students(id) on delete cascade,
  lesson_id uuid not null references lessons(id) on delete cascade,
  status text not null default 'locked', -- 'locked' | 'unlocked' | 'completed'
  session_id uuid references sessions(id), -- which session completed it, if any
  completed_date date,
  notes text,
  created_at timestamptz default now(),
  updated_at timestamptz default now(),
  unique (student_id, lesson_id)
);

create table report_templates (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  design_reference text,        -- reference to the Claude Design template asset
  is_default boolean not null default true,
  created_at timestamptz default now()
);

create table reports (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references students(id) on delete cascade,
  class_id uuid references classes(id),
  template_id uuid references report_templates(id),
  raw_notes text,                -- Gio's rough notes — input to the AI draft
  ai_draft_text text,            -- Claude API output, editable before export
  final_text text,               -- text actually exported to PDF
  final_pdf_url text,
  generated_date date not null default current_date,
  created_at timestamptz default now()
);

create table student_guardians (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references students(id) on delete cascade,
  guardian_id uuid not null references users(id) on delete cascade, -- users.role = 'parent'
  created_at timestamptz default now(),
  unique (student_id, guardian_id)
);

-- ============================================================
-- ARCHITECT NOW, BUILD LATER — Future phases
-- ============================================================
-- Deliberately empty. Every V2 item (academy-wide scheduling, Center Manager/Admin
-- screens, multi-center rollout, multiple report templates) reuses tables already
-- defined above via role/center_id — no speculative tables needed for v1.
-- Payments/CRM are permanently out of KOMS's remit (stay on OClass) — not modeled at all.

-- ============================================================
-- ROW LEVEL SECURITY
-- Non-negotiable: this data includes minors. A parent must never be able to
-- retrieve another family's student data under any query.
-- ============================================================

alter table centers enable row level security;
alter table users enable row level security;
alter table classes enable row level security;
alter table students enable row level security;
alter table enrollments enable row level security;
alter table sessions enable row level security;
alter table attendance enable row level security;
alter table session_videos enable row level security;
alter table report_templates enable row level security;
alter table reports enable row level security;
alter table student_guardians enable row level security;

-- A session log is one retriable database transaction. Without this RPC the
-- handler's session update, attendance upsert, and lesson upsert are separate
-- HTTP requests: a later failure can leave a half-logged session. This is
-- SECURITY INVOKER so every read/write remains under the caller's RLS policies.
create or replace function public.log_session(
  p_session_id uuid,
  p_notes text,
  p_attendance jsonb,
  p_lesson_completions jsonb
)
returns void
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_class_id uuid;
begin
  select s.class_id into v_class_id
  from public.sessions s
  where s.id = p_session_id
    and s.teacher_id = auth.uid()
  for update;

  if not found then
    raise insufficient_privilege using message = 'Not authorized to log this session';
  end if;

  if jsonb_typeof(p_attendance) <> 'array'
     or jsonb_typeof(p_lesson_completions) <> 'array' then
    raise invalid_parameter_value using message = 'Attendance and lesson completions must be arrays';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_attendance) as a("studentId" uuid, status text)
    left join public.enrollments e
      on e.student_id = a."studentId" and e.class_id = v_class_id
    where e.student_id is null or a.status not in ('present', 'absent')
  ) or exists (
    select 1
    from jsonb_to_recordset(p_attendance) as a("studentId" uuid, status text)
    group by a."studentId" having count(*) > 1
  ) then
    raise insufficient_privilege using message = 'Attendance contains an invalid or duplicate student';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(p_lesson_completions) as p("studentId" uuid, "lessonId" uuid)
    left join public.enrollments e
      on e.student_id = p."studentId" and e.class_id = v_class_id
    left join public.lessons l
      on l.id = p."lessonId" and l.class_id = v_class_id
    where e.student_id is null or l.id is null
  ) or exists (
    select 1
    from jsonb_to_recordset(p_lesson_completions) as p("studentId" uuid, "lessonId" uuid)
    group by p."studentId", p."lessonId" having count(*) > 1
  ) then
    raise insufficient_privilege using message = 'Lesson completion contains an invalid or duplicate record';
  end if;

  update public.sessions
  set status = 'completed', notes = p_notes, updated_at = now()
  where id = p_session_id;

  insert into public.attendance (session_id, student_id, status)
  select p_session_id, a."studentId", a.status
  from jsonb_to_recordset(p_attendance) as a("studentId" uuid, status text)
  on conflict (session_id, student_id) do update
    set status = excluded.status;

  insert into public.student_lesson_progress (
    student_id, lesson_id, status, session_id, completed_date, updated_at
  )
  select p."studentId", p."lessonId", 'completed', p_session_id,
    (now() at time zone 'Asia/Jakarta')::date, now()
  from jsonb_to_recordset(p_lesson_completions) as p("studentId" uuid, "lessonId" uuid)
  on conflict (student_id, lesson_id) do update set
    status = 'completed',
    session_id = excluded.session_id,
    completed_date = excluded.completed_date,
    updated_at = excluded.updated_at;
end;
$$;

revoke execute on function public.log_session(uuid, text, jsonb, jsonb) from public;
grant execute on function public.log_session(uuid, text, jsonb, jsonb) to authenticated;

-- ------------------------------------------------------------
-- CURRENT-USER HELPERS
-- ------------------------------------------------------------
-- A policy ON users may not read FROM users. While rewriting a query the
-- planner expands the policy, hits the subquery's reference to users, and
-- re-applies the same policy to it — Postgres detects the loop and aborts the
-- whole statement with 42P17 "infinite recursion detected in policy for
-- relation users". It is not a slow query or a subtle wrong answer: every
-- statement touching users fails, including proxy.ts's role lookup, which runs
-- on every authenticated request. The failure also propagates outward, because
-- policies on other tables (students_all_teacher and friends) read from users,
-- so expanding *those* re-enters users' policies and trips the same check.
--
-- security definer breaks the loop: the body runs as the function owner
-- (postgres, when this file is run from the SQL editor), and the owner is not
-- subject to RLS, so no policy is expanded inside it. plpgsql rather than sql
-- is deliberate — the planner inlines trivial sql functions, and an inlined
-- body would be back inside the caller's query tree with RLS applied again.
-- (`set search_path` already blocks inlining on its own; the language choice
-- keeps that from being load-bearing.) Both functions are scoped to
-- auth.uid(), so they expose nothing the caller can't already read from its
-- own row via users_select_own.
create or replace function public.current_user_role()
returns text
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  r text;
begin
  select role into r from public.users where id = auth.uid();
  return r;
end;
$$;

create or replace function public.current_user_center()
returns uuid
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  c uuid;
begin
  select center_id into c from public.users where id = auth.uid();
  return c;
end;
$$;

revoke execute on function public.current_user_role() from public;
revoke execute on function public.current_user_center() from public;
-- anon is granted too, deliberately. Policies are evaluated for whoever runs
-- the query, so a logged-out request touching report_templates would fail with
-- "permission denied for function" instead of the empty result the app expects.
-- Both functions key on auth.uid(), which is null for anon, so they return null
-- and every policy using them is simply false.
grant execute on function public.current_user_role() to authenticated, anon;
grant execute on function public.current_user_center() to authenticated, anon;

-- Breaks the students <-> student_guardians policy cycle.
--
-- student_guardians_all_teacher used to ask "is this student in my center?" with
-- a subquery on students. But students_select_parent answers itself with a
-- subquery on student_guardians, so each table's policy needed the other's
-- evaluated first and Postgres aborted the statement with 42P17 infinite
-- recursion -- on students, student_guardians, and every parent policy that
-- traverses them (enrollments, sessions, attendance, progress, reports).
--
-- security definer is what breaks it: the lookup inside runs without RLS, so it
-- never re-enters the policy that called it. Returning boolean rather than the
-- student's center_id keeps the promise the helpers above make -- it discloses
-- nothing, it answers the authorization question the caller is already entitled
-- to ask about itself, and it keys on auth.uid() the same way. plpgsql for the
-- same reason as the others: it cannot be inlined, so the search_path pin never
-- becomes load-bearing.
create or replace function public.is_staff_for_student(p_student_id uuid)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  ok boolean;
begin
  select exists (
    select 1
    from public.students s
    join public.users u on u.id = auth.uid()
    where s.id = p_student_id
      and u.role in ('teacher','center_manager','admin')
      and s.center_id = u.center_id
  ) into ok;
  return ok;
end;
$$;

revoke execute on function public.is_staff_for_student(uuid) from public;
grant execute on function public.is_staff_for_student(uuid) to authenticated, anon;

-- Breaks the classes <-> enrollments policy cycle, the second of the two.
--
-- enrollments_all_teacher asked "is this class mine?" by reading classes, while
-- classes_select_parent answers itself by reading enrollments -- so each table
-- again needed the other's policy evaluated first, and every query touching
-- either aborted with 42P17. Same shape as the students/student_guardians cycle
-- above, same remedy: move the lookup inside a security definer function, where
-- it runs without RLS and cannot re-enter the policy that called it.
--
-- Returns boolean for the same reason is_staff_for_student does: the caller
-- learns only whether it owns the class, which it is entitled to know, and
-- never reads a row out of classes through this path.
create or replace function public.is_teacher_of_class(p_class_id uuid)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  ok boolean;
begin
  select exists (
    select 1 from public.classes c
    where c.id = p_class_id and c.teacher_id = auth.uid()
  ) into ok;
  return ok;
end;
$$;

revoke execute on function public.is_teacher_of_class(uuid) from public;
grant execute on function public.is_teacher_of_class(uuid) to authenticated, anon;

-- users: everyone sees/updates only their own row
create policy "users_select_own" on users for select using (id = auth.uid());

-- WITH CHECK is spelled out deliberately. Postgres reuses the USING expression
-- as WITH CHECK when it is omitted, and "id = auth.uid()" still holds after a
-- row rewrites its OWN role — so the omitted form let any authenticated parent
-- run `update users set role='admin', center_id=<their child's class center>`
-- and inherit every *_admin_manage_center policy below. The anon key is public
-- by design, so that reaches PostgREST directly and never passes a route guard.
-- Column-level immutability is enforced by the trigger underneath; this clause
-- keeps the row-level intent readable at the policy site.
create policy "users_update_own" on users for update
  using (id = auth.uid())
  with check (id = auth.uid());

-- Role and center assignment are not self-service. Blocks only self-edits, so
-- an admin managing OTHER staff via users_admin_manage_center is unaffected,
-- as are service-role operations (auth.uid() is null there).
create or replace function prevent_self_privilege_escalation()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() = new.id
     and (new.role is distinct from old.role
          or new.center_id is distinct from old.center_id) then
    raise exception 'role and center_id cannot be changed by the account holder';
  end if;
  return new;
end;
$$;

-- create trigger has no "or replace"; the drop keeps a re-run of this file from
-- failing halfway, which matters while Step 7 is still being iterated on.
drop trigger if exists users_block_self_escalation on users;
create trigger users_block_self_escalation
  before update on users
  for each row execute function prevent_self_privilege_escalation();

-- centers: staff can see their own center
create policy "centers_select_staff" on centers for select using (
  id in (select center_id from users where id = auth.uid())
);

-- classes: teacher owns their classes; parent sees classes their child is enrolled in
-- WITH CHECK also pins center_id: with the inherited form a teacher could move
-- one of their own classes into another center, where that center's admin
-- policies would pick it up. Harmless in single-center v1, wrong the moment a
-- second center exists.
create policy "classes_all_teacher" on classes for all
  using (teacher_id = auth.uid())
  with check (
    teacher_id = auth.uid()
    and center_id in (select center_id from users where id = auth.uid())
  );
create policy "classes_select_parent" on classes for select using (
  id in (
    select e.class_id from enrollments e
    join student_guardians sg on sg.student_id = e.student_id
    where sg.guardian_id = auth.uid()
  )
);

-- students: teacher manages students in their center; parent sees only their linked child
create policy "students_all_teacher" on students for all using (
  center_id in (select center_id from users where id = auth.uid() and role in ('teacher','center_manager','admin'))
);
create policy "students_select_parent" on students for select using (
  id in (select student_id from student_guardians where guardian_id = auth.uid())
);

-- enrollments: teacher manages enrollments for their own classes; parent sees their child's
create policy "enrollments_all_teacher" on enrollments for all using (
  public.is_teacher_of_class(class_id)
);
create policy "enrollments_select_parent" on enrollments for select using (
  student_id in (select student_id from student_guardians where guardian_id = auth.uid())
);

-- sessions: teacher manages their own sessions; parent sees sessions for their child's classes
create policy "sessions_all_teacher" on sessions for all using (teacher_id = auth.uid());
create policy "sessions_select_parent" on sessions for select using (
  class_id in (
    select e.class_id from enrollments e
    join student_guardians sg on sg.student_id = e.student_id
    where sg.guardian_id = auth.uid()
  )
);

-- attendance: teacher manages for their sessions; parent sees only their own child's rows
-- Both halves are required. Gating on session_id alone lets a teacher who owns
-- the session write an attendance row for ANY student in the academy; the
-- enrollment clause pins student_id to the session's own class.
create policy "attendance_all_teacher" on attendance for all using (
  session_id in (select id from sessions where teacher_id = auth.uid())
  and student_id in (
    select e.student_id from enrollments e
    join sessions s on s.class_id = e.class_id
    where s.id = attendance.session_id
  )
);
create policy "attendance_select_parent" on attendance for select using (
  student_id in (select student_id from student_guardians where guardian_id = auth.uid())
);

-- session_videos: teacher manages for their sessions; parent sees videos tied to their child's sessions
create policy "session_videos_all_teacher" on session_videos for all using (
  session_id in (select id from sessions where teacher_id = auth.uid())
);
create policy "session_videos_select_parent" on session_videos for select using (
  session_id in (
    select a.session_id from attendance a
    join student_guardians sg on sg.student_id = a.student_id
    where sg.guardian_id = auth.uid()
  )
);

-- lessons: teacher/admin manage lessons for their own classes; parent/student can view
-- the lesson plan for classes their child is enrolled in (needed to render the journey)
alter table lessons enable row level security;
alter table student_lesson_progress enable row level security;

create policy "lessons_all_teacher" on lessons for all using (
  class_id in (select id from classes where teacher_id = auth.uid())
);
create policy "lessons_select_parent" on lessons for select using (
  class_id in (
    select e.class_id from enrollments e
    join student_guardians sg on sg.student_id = e.student_id
    where sg.guardian_id = auth.uid()
  )
);

-- student_lesson_progress: teacher manages for their students; parent sees only their own child's progress
-- As with attendance: the lesson clause alone would let a teacher mark any
-- student in the academy complete on one of their own lessons. The enrollment
-- clause pins student_id to a class that actually contains that lesson.
create policy "progress_all_teacher" on student_lesson_progress for all using (
  lesson_id in (
    select l.id from lessons l
    join classes c on c.id = l.class_id
    where c.teacher_id = auth.uid()
  )
  and student_id in (
    select e.student_id from enrollments e
    join lessons l on l.class_id = e.class_id
    where l.id = student_lesson_progress.lesson_id
  )
);
create policy "progress_select_parent" on student_lesson_progress for select using (
  student_id in (select student_id from student_guardians where guardian_id = auth.uid())
);

-- reports: teacher manages for their students; parent sees only their own child's reports
create policy "reports_all_teacher" on reports for all using (
  student_id in (
    select e.student_id from enrollments e
    join classes c on c.id = e.class_id
    where c.teacher_id = auth.uid()
  )
);
create policy "reports_select_parent" on reports for select using (
  student_id in (select student_id from student_guardians where guardian_id = auth.uid())
);

-- report_templates: any authenticated staff can read; Gio edits the row directly via
-- the Supabase dashboard in v1 — no in-app editor, per PRD Out of Scope.
-- "auth.uid() is not null" was every authenticated user, parents included —
-- the name said staff and the expression said anyone. Nothing in the parent
-- portal reads this table (only the two staff report pages do), so the narrow
-- form is what the app actually needs.
create policy "report_templates_select_staff" on report_templates for select using (
  (select public.current_user_role()) in ('teacher','center_manager','admin')
);

-- student_guardians: teacher creates links when adding a student's parent; parent sees only their own links
-- The role filter matches students_all_teacher above and is load-bearing: without
-- it, any user row whose center_id happens to be set — including a parent's —
-- would get ALL (insert/update/delete) on guardian links, letting them attach
-- themselves to another family's child and inherit every parent policy that
-- traverses student_guardians. The users_parent_has_no_center constraint closes
-- the same hole from the other side; both stay.
-- The role filter lives inside is_staff_for_student() now, but it is still
-- load-bearing for exactly the reason described above.
create policy "student_guardians_all_teacher" on student_guardians for all using (
  public.is_staff_for_student(student_id)
);
create policy "student_guardians_select_own" on student_guardians for select using (guardian_id = auth.uid());

-- ============================================================
-- ADMIN OVERRIDE POLICIES
-- role = 'admin' gets full access across the whole center — not just their
-- own classes/sessions. This is what powers Manage Teachers and Academy
-- Schedule. Scoped to center_id, not global, so it stays multi-tenant-safe
-- as more centers come online later.
-- ============================================================

-- Reads the caller's own role/center through the security definer helpers
-- rather than a subquery on users — see the CURRENT-USER HELPERS note above.
-- Each call is wrapped in (select ...) so the planner evaluates it once as an
-- InitPlan instead of once per candidate row.
-- WITH CHECK is spelled out for the same reason it is on users_update_own: the
-- inherited form would be identical here, but an admin editing staff is
-- exactly the path where an accidental widening would be worst.
-- center_manager is deliberately absent from the managed set, matching the
-- pre-existing policy — v1 has no such account, and adding one to the list is
-- a privilege decision, not a bug fix.
create policy "users_admin_manage_center" on users for all
  using (
    (select public.current_user_role()) = 'admin'
    and role in ('teacher','admin')
    and center_id = (select public.current_user_center())
  )
  with check (
    (select public.current_user_role()) = 'admin'
    and role in ('teacher','admin')
    and center_id = (select public.current_user_center())
  );

create policy "classes_admin_manage_center" on classes for all using (
  center_id in (select center_id from users where id = auth.uid() and role = 'admin')
);

create policy "sessions_admin_manage_center" on sessions for all using (
  class_id in (
    select id from classes where center_id in (
      select center_id from users where id = auth.uid() and role = 'admin'
    )
  )
);

create policy "lessons_admin_manage_center" on lessons for all using (
  class_id in (
    select id from classes where center_id in (
      select center_id from users where id = auth.uid() and role = 'admin'
    )
  )
);

-- Report publication boundary (also supplied as a forward migration).
-- Apply once to the existing KodeHub schema. Existing reports stay private.
begin;

alter table public.reports add column pdf_storage_path text;
drop policy if exists "reports_select_parent" on public.reports;

-- Stable class scope, not merely another class that happens to share a student.
create or replace function public.can_manage_report(p_student uuid, p_class uuid)
returns boolean language sql stable security definer set search_path = public
as $$
  select exists (
    select 1 from public.users u
    join public.classes c on c.id = p_class and c.center_id = u.center_id
    join public.students s on s.id = p_student and s.center_id = c.center_id
    where u.id = auth.uid() and
      (u.role = 'admin' or (u.role = 'teacher' and c.teacher_id = u.id))
  );
$$;
revoke all on function public.can_manage_report(uuid, uuid) from public, anon;
grant execute on function public.can_manage_report(uuid, uuid) to authenticated;

drop policy "reports_all_teacher" on public.reports;
create policy "reports_manage_staff" on public.reports for all to authenticated
  using (public.can_manage_report(student_id, class_id))
  with check (
    public.can_manage_report(student_id, class_id)
    and exists (select 1 from public.enrollments e
      where e.student_id = reports.student_id and e.class_id = reports.class_id)
  );

create table public.published_reports (
  id uuid primary key default gen_random_uuid(),
  report_id uuid not null unique references public.reports(id),
  student_id uuid not null references public.students(id),
  class_id uuid not null references public.classes(id),
  final_text text not null check (length(trim(final_text)) > 0),
  generated_date date not null,
  pdf_storage_path text not null,
  published_by uuid not null references public.users(id),
  published_at timestamptz not null default now(),
  withdrawn_at timestamptz
);
alter table public.published_reports enable row level security;
grant select on public.published_reports to authenticated;
create policy "published_reports_staff_read" on public.published_reports
  for select to authenticated using (public.can_manage_report(student_id, class_id));
create policy "published_reports_family_read" on public.published_reports
  for select to authenticated using (
    withdrawn_at is null and exists (
      select 1 from public.student_guardians g
      where g.student_id = published_reports.student_id and g.guardian_id = auth.uid()
    )
  );

-- No client INSERT/UPDATE/DELETE policy. Only these narrowly scoped RPCs write.
create or replace function public.publish_report(p_report_id uuid)
returns uuid language plpgsql security definer set search_path = public
as $$
declare r public.reports; publication_id uuid;
begin
  select * into r from public.reports where id = p_report_id for update;
  if not found or not public.can_manage_report(r.student_id, r.class_id) then
    raise exception 'Report not found' using errcode = '42501';
  end if;
  if r.final_text is null or length(trim(r.final_text)) = 0
    or r.pdf_storage_path is distinct from r.student_id::text || '/' || r.id::text || '.pdf' then
    raise exception 'Export a PDF before publishing' using errcode = '23514';
  end if;
  if not exists (select 1 from storage.objects where bucket_id = 'reports' and name = r.pdf_storage_path) then
    raise exception 'Export a PDF before publishing' using errcode = '23514';
  end if;
  insert into public.published_reports
    (report_id, student_id, class_id, final_text, generated_date, pdf_storage_path, published_by)
  values (r.id, r.student_id, r.class_id, r.final_text, r.generated_date, r.pdf_storage_path, auth.uid())
  on conflict (report_id) do nothing returning id into publication_id;
  if publication_id is null then
    select id into publication_id from public.published_reports where report_id = r.id;
  end if;
  -- A retry never reopens a withdrawn snapshot. Export a new version to republish.
  return publication_id;
end;
$$;

create or replace function public.withdraw_report(p_publication_id uuid)
returns void language plpgsql security definer set search_path = public
as $$
declare r public.published_reports;
begin
  select * into r from public.published_reports where id = p_publication_id for update;
  if not found or not public.can_manage_report(r.student_id, r.class_id) then
    raise exception 'Report not found' using errcode = '42501';
  end if;
  update public.published_reports set withdrawn_at = coalesce(withdrawn_at, now())
    where id = r.id;
end;
$$;
revoke all on function public.publish_report(uuid) from public, anon;
revoke all on function public.withdraw_report(uuid) from public, anon;
grant execute on function public.publish_report(uuid) to authenticated;
grant execute on function public.withdraw_report(uuid) to authenticated;

commit;

-- Credit ledger boundary (also supplied as a forward migration).
-- Apply once, after report publications. Existing sessions are billing-exempt.
begin;
alter table public.sessions add column credit_billable boolean not null default false;
alter table public.sessions alter column credit_billable set default true;
alter table public.sessions add column revision integer not null default 0 check (revision >= 0);

create table public.credit_accounts (
  student_id uuid primary key references public.students(id),
  balance integer not null default 0 check (balance >= 0),
  revision integer not null default 0 check (revision >= 0)
);
create table public.credit_operations (
  actor_id uuid not null references public.users(id),
  request_id uuid not null,
  payload jsonb not null,
  result jsonb not null,
  created_at timestamptz not null default now(),
  primary key (actor_id, request_id)
);
create table public.credit_entries (
  id uuid primary key default gen_random_uuid(),
  student_id uuid not null references public.credit_accounts(student_id),
  amount integer not null check (amount <> 0),
  kind text not null check (kind in ('top_up','adjustment','attendance_charge','attendance_refund')),
  reason text not null check (length(trim(reason)) between 1 and 500),
  actor_id uuid not null references public.users(id),
  request_id uuid not null,
  session_id uuid references public.sessions(id),
  effective_date date not null,
  recorded_at timestamptz not null default now(),
  unique (actor_id, request_id, student_id),
  foreign key (actor_id, request_id) references public.credit_operations(actor_id, request_id) deferrable initially deferred,
  check ((kind = 'top_up' and amount > 0 and session_id is null)
    or (kind = 'adjustment' and session_id is null)
    or (kind = 'attendance_charge' and amount = -1 and session_id is not null)
    or (kind = 'attendance_refund' and amount = 1 and session_id is not null))
);
create table public.session_credit_state (
  session_id uuid not null references public.sessions(id),
  student_id uuid not null references public.credit_accounts(student_id),
  charged boolean not null,
  primary key (session_id, student_id)
);
create index credit_entries_student_history on public.credit_entries(student_id, recorded_at desc, id desc);
insert into public.credit_accounts(student_id) select id from public.students;

create or replace function public.can_read_credits(p_student uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.users u join public.students s on s.id = p_student
    where u.id = auth.uid() and (
      (u.role = 'admin' and u.center_id = s.center_id)
      or (u.role = 'teacher' and u.center_id = s.center_id and exists (
        select 1 from public.enrollments e join public.classes c on c.id = e.class_id
        where e.student_id = s.id and c.teacher_id = u.id and c.center_id = u.center_id))
      or (u.role = 'parent' and exists (select 1 from public.student_guardians g
        where g.student_id = s.id and g.guardian_id = u.id))));
$$;
alter table public.credit_accounts enable row level security;
alter table public.credit_entries enable row level security;
alter table public.credit_operations enable row level security;
alter table public.session_credit_state enable row level security;
create policy "credit_accounts_read" on public.credit_accounts for select to authenticated
  using (public.can_read_credits(student_id));
create policy "credit_entries_read" on public.credit_entries for select to authenticated
  using (public.can_read_credits(student_id));
create policy "credit_operations_private" on public.credit_operations for select using (false);
create policy "session_credit_state_private" on public.session_credit_state for select using (false);
grant select on public.credit_accounts, public.credit_entries to authenticated;

-- Direct attendance writes and billing-flag edits would bypass the ledger.
-- Definer RPCs execute as the schema owner; ordinary PostgREST users do not.
create or replace function public.guard_credit_writes()
returns trigger language plpgsql set search_path = public as $$
begin
  if current_user in ('authenticated', 'anon') then
    if tg_table_name = 'attendance' then
      raise exception 'Use the session logging RPC' using errcode = '42501';
    elsif tg_op = 'INSERT' then
      if not new.credit_billable or new.revision <> 0 or new.status <> 'scheduled' then
        raise exception 'Invalid new session billing state' using errcode = '42501';
      end if;
    elsif new.credit_billable is distinct from old.credit_billable
      or new.revision is distinct from old.revision or new.class_id is distinct from old.class_id
      or new.status is distinct from old.status or new.notes is distinct from old.notes then
      raise exception 'Use the session logging RPC' using errcode = '42501';
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;
create trigger attendance_credit_guard before insert or update or delete on public.attendance
  for each row execute function public.guard_credit_writes();
create trigger session_credit_guard before insert or update on public.sessions
  for each row execute function public.guard_credit_writes();

create or replace function public.adjust_credits(p_student uuid, p_amount integer, p_kind text, p_reason text, p_request uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare v_payload jsonb; v_receipt public.credit_operations; v_balance integer; v_result jsonb;
begin
  if not exists (select 1 from public.users u join public.students s on s.center_id = u.center_id
      where u.id = auth.uid() and u.role = 'admin' and s.id = p_student) then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  if p_request is null or p_amount is null or p_amount = 0 or abs(p_amount::bigint) > 10000
    or p_kind is null or p_kind not in ('top_up','adjustment') or (p_kind = 'top_up' and p_amount < 0)
    or p_reason is null or length(trim(p_reason)) not between 1 and 500 then
    raise exception 'Invalid credit adjustment' using errcode = '22023';
  end if;
  v_payload := jsonb_build_object('operation','adjust','student',p_student,'amount',p_amount,'kind',p_kind,'reason',trim(p_reason));
  perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text || p_request::text, 0));
  select * into v_receipt from public.credit_operations where actor_id = auth.uid() and request_id = p_request;
  if found then
    if v_receipt.payload <> v_payload then raise exception 'Request ID already used for different data' using errcode = 'P0002'; end if;
    return v_receipt.result;
  end if;
  insert into public.credit_accounts(student_id) values (p_student) on conflict do nothing;
  select balance into v_balance from public.credit_accounts where student_id = p_student for update;
  if v_balance::bigint + p_amount < 0 or v_balance::bigint + p_amount > 2147483647 then
    raise exception 'Insufficient credits or balance limit exceeded' using errcode = 'P0001';
  end if;
  update public.credit_accounts set balance = balance + p_amount, revision = revision + 1 where student_id = p_student;
  insert into public.credit_entries(student_id,amount,kind,reason,actor_id,request_id,effective_date)
    values (p_student,p_amount,p_kind,trim(p_reason),auth.uid(),p_request,(now() at time zone 'Asia/Jakarta')::date);
  v_result := jsonb_build_object('balance',v_balance + p_amount);
  insert into public.credit_operations(actor_id,request_id,payload,result) values(auth.uid(),p_request,v_payload,v_result);
  return v_result;
end;
$$;

create or replace function public.log_session_credits(
  p_session_id uuid, p_notes text, p_attendance jsonb, p_lesson_completions jsonb,
  p_request uuid, p_expected_revision integer
)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_session public.sessions; v_payload jsonb; v_receipt public.credit_operations;
  a record; v_charged boolean; v_delta integer; v_balance integer; v_result jsonb;
begin
  if auth.uid() is null or p_request is null or p_expected_revision is null or p_expected_revision < 0 then
    raise exception 'Invalid request identity or revision' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text || p_request::text, 0));
  select * into v_session from public.sessions where id = p_session_id for update;
  if not found or not exists (select 1 from public.users u join public.classes c on c.center_id = u.center_id
    where u.id = auth.uid() and c.id = v_session.class_id and
      (u.role = 'admin' or (u.role = 'teacher' and c.teacher_id = u.id and v_session.teacher_id = u.id))) then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  v_payload := jsonb_build_object('operation','log','session',p_session_id,'notes',p_notes,
    'attendance',p_attendance,'lessons',p_lesson_completions,'revision',p_expected_revision);
  select * into v_receipt from public.credit_operations where actor_id = auth.uid() and request_id = p_request;
  if found then
    if v_receipt.payload <> v_payload then raise exception 'Request ID already used for different data' using errcode = 'P0002'; end if;
    return v_receipt.result;
  end if;
  if v_session.revision <> p_expected_revision then raise exception 'Session changed. Reload before saving.' using errcode = 'P0002'; end if;
  if jsonb_typeof(p_attendance) is distinct from 'array' or jsonb_typeof(p_lesson_completions) is distinct from 'array'
    or length(coalesce(p_notes,'')) > 10000 then
    raise exception 'Invalid session payload' using errcode = '22023';
  end if;
  if jsonb_array_length(p_attendance) > 500 or jsonb_array_length(p_lesson_completions) > 5000 then
    raise exception 'Session payload too large' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_to_recordset(p_attendance) as x("studentId" uuid,status text)
    left join public.students s on s.id = x."studentId"
    join public.classes c on c.id = v_session.class_id
    where s.id is null or s.center_id <> c.center_id or x.status is null or x.status not in ('present','absent','unmarked')
    or (not exists (select 1 from public.enrollments e where e.student_id = x."studentId" and e.class_id = c.id)
      and not (x.status in ('absent','unmarked') and exists (select 1 from public.session_credit_state sc
        where sc.session_id = p_session_id and sc.student_id = x."studentId" and sc.charged))))
    or exists (select 1 from jsonb_to_recordset(p_attendance) as x("studentId" uuid)
      group by x."studentId" having count(*) > 1) then
    raise exception 'Invalid attendance scope' using errcode = '42501';
  end if;
  if exists (select 1 from jsonb_to_recordset(p_lesson_completions) as x("studentId" uuid,"lessonId" uuid)
    left join public.enrollments e on e.student_id = x."studentId" and e.class_id = v_session.class_id
    left join public.lessons l on l.id = x."lessonId" and l.class_id = v_session.class_id
    left join public.students s on s.id = x."studentId"
    join public.classes c on c.id = v_session.class_id
    where e.id is null or l.id is null or s.center_id <> c.center_id)
    or exists (select 1 from jsonb_to_recordset(p_lesson_completions) as x("studentId" uuid,"lessonId" uuid)
      group by x."studentId", x."lessonId" having count(*) > 1) then
    raise exception 'Invalid lesson scope' using errcode = '42501';
  end if;
  if v_session.credit_billable then
    -- Stable ordering prevents two class logs from locking shared learners in reverse order.
    for a in select * from jsonb_to_recordset(p_attendance) as x("studentId" uuid,status text) order by x."studentId" loop
      insert into public.credit_accounts(student_id) values(a."studentId") on conflict do nothing;
      select balance into v_balance from public.credit_accounts where student_id = a."studentId" for update;
      select charged into v_charged from public.session_credit_state where session_id = p_session_id and student_id = a."studentId";
      v_delta := coalesce(v_charged,false)::integer - (a.status = 'present')::integer;
      if v_balance::bigint + v_delta < 0 or v_balance::bigint + v_delta > 2147483647 then
        raise exception 'Credit balance would be out of range' using errcode = 'P0001';
      end if;
      if v_delta <> 0 then
        update public.credit_accounts set balance = balance + v_delta, revision = revision + 1 where student_id = a."studentId";
        insert into public.credit_entries(student_id,amount,kind,reason,actor_id,request_id,session_id,effective_date)
          values(a."studentId",v_delta,case when v_delta < 0 then 'attendance_charge' else 'attendance_refund' end,
            case when v_delta < 0 then 'Session attendance' else 'Attendance correction' end,
            auth.uid(),p_request,p_session_id,v_session.session_date);
      end if;
      insert into public.session_credit_state(session_id,student_id,charged) values(p_session_id,a."studentId",a.status = 'present')
        on conflict(session_id,student_id) do update set charged = excluded.charged;
    end loop;
  end if;
  update public.sessions set status = 'completed', notes = p_notes, revision = revision + 1, updated_at = now() where id = p_session_id;
  insert into public.attendance(session_id,student_id,status)
    select p_session_id,x."studentId",x.status from jsonb_to_recordset(p_attendance) as x("studentId" uuid,status text)
    on conflict(session_id,student_id) do update set status = excluded.status;
  insert into public.student_lesson_progress(student_id,lesson_id,status,session_id,completed_date,updated_at)
    select x."studentId",x."lessonId",'completed',p_session_id,(now() at time zone 'Asia/Jakarta')::date,now()
    from jsonb_to_recordset(p_lesson_completions) as x("studentId" uuid,"lessonId" uuid)
    on conflict(student_id,lesson_id) do update set status = 'completed',session_id = excluded.session_id,
      completed_date = excluded.completed_date,updated_at = excluded.updated_at;
  v_result := jsonb_build_object('revision',v_session.revision + 1);
  insert into public.credit_operations(actor_id,request_id,payload,result) values(auth.uid(),p_request,v_payload,v_result);
  return v_result;
end;
$$;

revoke all on function public.log_session(uuid,text,jsonb,jsonb) from public,anon,authenticated;
revoke all on function public.can_read_credits(uuid) from public,anon;
revoke all on function public.adjust_credits(uuid,integer,text,text,uuid) from public,anon;
revoke all on function public.log_session_credits(uuid,text,jsonb,jsonb,uuid,integer) from public,anon;
grant execute on function public.can_read_credits(uuid) to authenticated;
grant execute on function public.adjust_credits(uuid,integer,text,text,uuid) to authenticated;
grant execute on function public.log_session_credits(uuid,text,jsonb,jsonb,uuid,integer) to authenticated;
commit;

-- Reusable course library (also supplied as a forward migration).
begin;

-- Reusable courses do not change existing class lessons or learner progress.
alter table users add constraint users_id_center_unique unique (id, center_id);
create table courses (
  id uuid primary key,
  center_id uuid not null references centers(id),
  owner_id uuid not null,
  title text not null check (length(btrim(title)) between 1 and 200),
  category text not null check (length(category) <= 100),
  age_range text not null check (length(age_range) <= 100),
  level text not null check (length(level) <= 100),
  description text not null check (length(description) <= 10000),
  prerequisites text not null check (length(prerequisites) <= 10000),
  lesson_count integer not null default 0 check (lesson_count between 0 and 10000),
  revision integer not null default 1 check (revision > 0),
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (owner_id, center_id) references users(id, center_id)
);
create index courses_center_id_idx on courses(center_id, id);

create table course_lessons (
  id uuid primary key,
  course_id uuid not null references courses(id),
  sequence integer not null check (sequence between 1 and 10000),
  title text not null check (length(btrim(title)) between 1 and 200),
  minutes integer not null check (minutes between 1 and 1440),
  objective text not null check (length(objective) <= 10000),
  materials text not null check (length(materials) <= 10000),
  steps text not null check (length(steps) <= 20000),
  evidence text not null check (length(evidence) <= 10000),
  revision integer not null default 1 check (revision > 0),
  archived_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (course_id, sequence)
);

create table course_write_receipts (
  actor_id uuid not null references users(id),
  request_id uuid not null,
  payload jsonb not null,
  result jsonb not null,
  created_at timestamptz not null default now(),
  primary key (actor_id, request_id)
);
create table course_target_write_receipts (
  actor_id uuid not null references users(id),
  request_id uuid not null,
  payload jsonb not null,
  result jsonb not null,
  created_at timestamptz not null default now(),
  primary key (actor_id, request_id)
);
alter table courses enable row level security;
alter table course_lessons enable row level security;
alter table course_write_receipts enable row level security;
alter table course_target_write_receipts enable row level security;
revoke all on course_target_write_receipts from public,anon,authenticated;
create policy "courses_read_staff" on courses for select to authenticated
  using (center_id = public.current_user_center() and public.current_user_role() in ('teacher','admin'));
create policy "course_lessons_read_staff" on course_lessons for select to authenticated
  using (exists (select 1 from courses c where c.id = course_lessons.course_id
    and c.center_id = public.current_user_center()
    and public.current_user_role() in ('teacher','admin')));
create policy "course_receipts_private" on course_write_receipts for select to authenticated using (false);
create policy "course_target_receipts_private" on course_target_write_receipts for select to authenticated using (false);
-- No client mutation policies; receipts remain private to the RPC.

-- Full content replacement with optimistic revisions. Revision 0 creates a row.
-- The course lock also serializes lesson edits against course archiving.
create function public.save_course_content(
  p_course uuid, p_lesson uuid, p_expected_revision integer,
  p_request uuid, p_content jsonb
) returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_actor uuid := auth.uid();
  v_role text;
  v_center uuid;
  v_course courses%rowtype;
  v_lesson course_lessons%rowtype;
  v_receipt course_write_receipts%rowtype;
  v_payload jsonb;
  v_result jsonb;
  v_fields text[];
  v_key text;
  v_revision integer;
  v_archived timestamptz;
begin
  select role, center_id into v_role, v_center from users where id = v_actor;
  if v_actor is null or v_center is null or v_role not in ('teacher','admin') then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  if p_course is null or p_request is null or p_expected_revision is null or p_expected_revision < 0
     or p_content is null or jsonb_typeof(p_content) <> 'object' then
    raise exception 'Invalid content' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('course-request:' || v_actor::text || ':' || p_request::text, 0));
  perform pg_advisory_xact_lock(hashtextextended('course:' || p_course::text, 0));
  select * into v_course from courses where id = p_course for update;
  if v_course.id is not null and (v_course.center_id <> v_center or (v_role <> 'admin' and v_course.owner_id <> v_actor)) then
    raise exception 'Not authorized' using errcode = '42501';
  end if;
  if v_course.id is null and (p_lesson is not null or p_expected_revision <> 0) then
    raise exception 'Not found' using errcode = '42501';
  end if;
  v_payload := jsonb_build_object('course',p_course,'lesson',p_lesson,'revision',p_expected_revision,'content',p_content);
  select * into v_receipt from course_write_receipts where actor_id = v_actor and request_id = p_request;
  if found then
    if v_receipt.payload <> v_payload then
      raise exception 'Request reused' using errcode = 'P0002';
    end if;
    return v_receipt.result;
  end if;
  v_fields := case when p_lesson is null
    then array['title','category','age_range','level','description','prerequisites']
    else array['title','objective','materials','steps','evidence'] end;
  foreach v_key in array v_fields loop
    if jsonb_typeof(p_content->v_key) is distinct from 'string' then
      raise exception 'Invalid text field' using errcode = '22023';
    end if;
  end loop;
  v_fields := v_fields || array['archived'];
  if p_lesson is not null then
    v_fields := v_fields || array['sequence','minutes'];
    if jsonb_typeof(p_content->'sequence') is distinct from 'number'
       or jsonb_typeof(p_content->'minutes') is distinct from 'number'
       or (p_content->>'sequence') !~ '^[0-9]+$' or (p_content->>'minutes') !~ '^[0-9]+$' then
      raise exception 'Invalid lesson numbers' using errcode = '22023';
    end if;
  end if;
  if jsonb_typeof(p_content->'archived') is distinct from 'boolean'
     or exists (select 1 from jsonb_object_keys(p_content) k where not (k = any(v_fields))) then
    raise exception 'Invalid fields' using errcode = '22023';
  end if;
  if p_lesson is null then
    v_revision := coalesce(v_course.revision, 0);
    v_archived := v_course.archived_at;
  else
    if v_course.archived_at is not null then
      raise exception 'Restore course before editing lessons' using errcode = 'P0002';
    end if;
    -- Also lock absent lesson IDs: two courses must not concurrently create the
    -- same lesson ID and reach an UPSERT against another course's content.
    perform pg_advisory_xact_lock(hashtextextended('course-lesson:' || p_lesson::text, 0));
    -- Also lock absent lesson IDs: two courses must not concurrently create the
    -- same lesson ID and reach an UPSERT against another course's content.
    perform pg_advisory_xact_lock(hashtextextended('course-lesson:' || p_lesson::text, 0));
    select * into v_lesson from course_lessons where id = p_lesson for update;
    if v_lesson.id is not null and v_lesson.course_id <> p_course then
      raise exception 'Not authorized' using errcode = '42501';
    end if;
    v_revision := coalesce(v_lesson.revision, 0);
    v_archived := v_lesson.archived_at;
  end if;
  if v_revision <> p_expected_revision then
    raise exception 'Stale revision' using errcode = 'P0002';
  end if;
  v_archived := case when (p_content->>'archived')::boolean then coalesce(v_archived, now()) else null end;
  if p_lesson is null then
    insert into courses(id,center_id,owner_id,title,category,age_range,level,description,prerequisites,archived_at)
    values(p_course,v_center,v_actor,p_content->>'title',p_content->>'category',p_content->>'age_range',
      p_content->>'level',p_content->>'description',p_content->>'prerequisites',v_archived)
    on conflict(id) do update set title=excluded.title, category=excluded.category, age_range=excluded.age_range,
      level=excluded.level, description=excluded.description, prerequisites=excluded.prerequisites,
      archived_at=excluded.archived_at, revision=courses.revision+1, updated_at=now();
  else
    insert into course_lessons(id,course_id,sequence,title,minutes,objective,materials,steps,evidence,archived_at)
    values(p_lesson,p_course,(p_content->>'sequence')::integer,p_content->>'title',(p_content->>'minutes')::integer,
      p_content->>'objective',p_content->>'materials',p_content->>'steps',p_content->>'evidence',v_archived)
    on conflict(id) do update set sequence=excluded.sequence,title=excluded.title,minutes=excluded.minutes,
      objective=excluded.objective,materials=excluded.materials,steps=excluded.steps,evidence=excluded.evidence,
      archived_at=excluded.archived_at, revision=course_lessons.revision+1,updated_at=now();
  end if;
  v_result := jsonb_build_object('id',coalesce(p_lesson,p_course),'revision',v_revision+1);
  insert into course_write_receipts(actor_id,request_id,payload,result) values(v_actor,p_request,v_payload,v_result);
  return v_result;
end;
$$;
revoke all on function public.save_course_content(uuid,uuid,integer,uuid,jsonb) from public,anon;
grant execute on function public.save_course_content(uuid,uuid,integer,uuid,jsonb) to authenticated;
grant select on courses,course_lessons to authenticated;
-- TRUNCATE bypasses RLS; Supabase bootstrap privileges must not permit it.
revoke truncate on courses,course_lessons,course_write_receipts,course_target_write_receipts from public,anon,authenticated;
commit;

-- Class course assignment history (also supplied as a forward migration).
begin;

alter table classes add constraint classes_id_center_unique unique (id, center_id);
alter table courses add constraint courses_id_center_unique unique (id, center_id);

create table class_course_assignments (
  id uuid primary key default gen_random_uuid(),
  class_id uuid not null,
  center_id uuid not null,
  course_id uuid not null,
  assigned_by uuid not null references users(id),
  assigned_at timestamptz not null default now(),
  ended_at timestamptz,
  foreign key (class_id, center_id) references classes(id, center_id),
  foreign key (course_id, center_id) references courses(id, center_id),
  unique (id, class_id)
);
create unique index class_course_one_active_per_class
  on class_course_assignments(class_id) where ended_at is null;
create index class_course_history_idx on class_course_assignments(class_id, assigned_at desc, id);

create table class_course_write_receipts (
  actor_id uuid not null references users(id),
  request_id uuid not null,
  payload jsonb not null,
  result jsonb not null,
  created_at timestamptz not null default now(),
  primary key (actor_id, request_id)
);

alter table class_course_assignments enable row level security;
alter table class_course_write_receipts enable row level security;
create policy "class_course_assignments_read_staff" on class_course_assignments for select to authenticated
using (
  (public.current_user_role() = 'teacher' and public.is_teacher_of_class(class_id)) or
  (public.current_user_role() = 'admin' and center_id = public.current_user_center())
);
create policy "class_course_assignments_read_guardian_active_class" on class_course_assignments for select to authenticated
using (
  ended_at is null and exists (
    select 1 from enrollments e
    join student_guardians sg on sg.student_id = e.student_id
    where e.class_id = class_course_assignments.class_id and sg.guardian_id = auth.uid()
  )
);
create policy "courses_read_guardian_active_class" on courses for select to authenticated
using (
  archived_at is null and exists (
    select 1 from class_course_assignments ca
    join enrollments e on e.class_id = ca.class_id
    join student_guardians sg on sg.student_id = e.student_id
    where ca.course_id = courses.id and ca.ended_at is null and sg.guardian_id = auth.uid()
  )
);
create policy "class_course_receipts_private" on class_course_write_receipts for select to authenticated using (false);
grant select on class_course_assignments to authenticated;
revoke truncate on class_course_assignments,class_course_write_receipts from public,anon,authenticated;

create function public.set_class_course(p_class uuid, p_course uuid, p_request uuid)
returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_actor uuid := auth.uid();
  v_role text;
  v_user_center uuid;
  v_center uuid;
  v_active class_course_assignments%rowtype;
  v_receipt class_course_write_receipts%rowtype;
  v_payload jsonb;
  v_result jsonb;
begin
  select role,center_id into v_role,v_user_center from users where id = v_actor;
  if v_actor is null or v_role is null or v_role not in ('teacher','admin') then
    raise exception 'Not authorized' using errcode='42501';
  end if;
  if p_class is null or p_request is null then
    raise exception 'Invalid request' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('class-course-request:'||v_actor::text||':'||p_request::text,0));
  perform pg_advisory_xact_lock(hashtextextended('class-course:'||p_class::text,0));
  select center_id into v_center from classes where id=p_class for update;
  if v_center is null or
    (v_role='teacher' and (v_user_center is distinct from v_center or not public.is_teacher_of_class(p_class))) or
    (v_role='admin' and v_user_center is distinct from v_center) then
    raise exception 'Not authorized' using errcode='42501';
  end if;
  v_payload:=jsonb_build_object('class',p_class,'course',p_course);
  select * into v_receipt from class_course_write_receipts where actor_id=v_actor and request_id=p_request;
  if found then
    if v_receipt.payload<>v_payload then raise exception 'Request reused' using errcode='P0002'; end if;
    return v_receipt.result;
  end if;
  select * into v_active from class_course_assignments where class_id=p_class and ended_at is null for update;
  if p_course is not null then
    perform 1 from courses where id=p_course and center_id=v_center and archived_at is null;
    if not found then raise exception 'Course unavailable' using errcode='42501'; end if;
  end if;
  if v_active.id is not null and v_active.course_id is not distinct from p_course then
    v_result:=jsonb_build_object('id',v_active.id,'courseId',p_course,'changed',false);
  else
    if v_active.id is not null then
      update class_course_assignments set ended_at=now() where id=v_active.id;
    end if;
    if p_course is null then
      v_result:=jsonb_build_object('id',null,'courseId',null,'changed',v_active.id is not null);
    else
      insert into class_course_assignments(class_id,center_id,course_id,assigned_by)
        values(p_class,v_center,p_course,v_actor) returning id into v_active.id;
      v_result:=jsonb_build_object('id',v_active.id,'courseId',p_course,'changed',true);
    end if;
  end if;
  insert into class_course_write_receipts(actor_id,request_id,payload,result)
    values(v_actor,p_request,v_payload,v_result);
  return v_result;
end;
$$;
revoke all on function public.set_class_course(uuid,uuid,uuid) from public,anon;
grant execute on function public.set_class_course(uuid,uuid,uuid) to authenticated;
commit;

-- Class assignments and publication snapshots (also supplied as a forward migration).
begin;

alter table students add constraint students_id_center_unique unique (id,center_id);

alter table class_course_assignments add constraint class_course_assignment_composite_unique
  unique (id,class_id,course_id,center_id);
alter table course_lessons add constraint course_lessons_id_course_unique unique (id,course_id);

create table assignments (
  id uuid primary key,
  class_id uuid not null,
  center_id uuid not null,
  course_assignment_id uuid not null,
  course_id uuid not null,
  course_lesson_id uuid,
  title text not null check (length(btrim(title)) between 1 and 200),
  brief text not null check (length(brief) <= 20000),
  due_at timestamptz,
  status text not null default 'draft' check (status in ('draft','published','archived')),
  lesson_title_snapshot text,
  lesson_objective_snapshot text,
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null references users(id),
  updated_by uuid not null references users(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  published_at timestamptz,
  foreign key (course_assignment_id,class_id,course_id,center_id)
    references class_course_assignments(id,class_id,course_id,center_id),
  foreign key (class_id,center_id) references classes(id,center_id),
  foreign key (course_lesson_id,course_id) references course_lessons(id,course_id),
  unique (id,class_id),
  check ((status='draft' and published_at is null) or status in ('published','archived'))
);
create index assignments_class_idx on assignments(class_id,status,updated_at desc,id);

create table assignment_learners (
  assignment_id uuid not null,
  class_id uuid not null,
  center_id uuid not null,
  student_id uuid not null,
  assigned_at timestamptz not null default now(),
  submission_open boolean not null default true,
  primary key (assignment_id,student_id),
  foreign key (assignment_id,class_id) references assignments(id,class_id),
  foreign key (class_id,center_id) references classes(id,center_id),
  foreign key (student_id,center_id) references students(id,center_id)
);
create index assignment_learners_student_idx on assignment_learners(student_id,assigned_at desc,assignment_id);

create table assignment_write_receipts (
  actor_id uuid not null references users(id), request_id uuid not null,
  payload jsonb not null, result jsonb not null, created_at timestamptz not null default now(),
  primary key(actor_id,request_id)
);

create function public.can_manage_class(p_class uuid)
returns boolean language sql stable security definer set search_path=public,pg_temp as $$
  select exists (
    select 1 from classes c join users u on u.id=auth.uid()
    where c.id=p_class and (
      (u.role='teacher' and u.center_id=c.center_id and c.teacher_id=u.id) or
      (u.role='admin' and u.center_id=c.center_id)
    )
  )
$$;
create function public.can_read_assignment(p_assignment uuid,p_student uuid default null)
returns boolean language sql stable security definer set search_path=public,pg_temp as $$
  select exists (
    select 1 from assignments a join assignment_learners al on al.assignment_id=a.id
    join student_guardians sg on sg.student_id=al.student_id
    join users u on u.id=auth.uid()
    where a.id=p_assignment and a.status in ('published','archived')
      and u.role='parent' and sg.guardian_id=u.id
      and (p_student is null or al.student_id=p_student)
  )
$$;
revoke all on function public.can_manage_class(uuid) from public;
revoke all on function public.can_read_assignment(uuid,uuid) from public;
grant execute on function public.can_manage_class(uuid),public.can_read_assignment(uuid,uuid) to authenticated;

alter table assignments enable row level security;
alter table assignment_learners enable row level security;
alter table assignment_write_receipts enable row level security;
create policy "assignments_read_staff_or_family" on assignments for select to authenticated
using (public.can_manage_class(class_id) or public.can_read_assignment(id,null));
create policy "assignment_learners_read_staff_or_family" on assignment_learners for select to authenticated
using (public.can_manage_class(class_id) or public.can_read_assignment(assignment_id,student_id));
create policy "assignment_receipts_private" on assignment_write_receipts for select to authenticated using(false);
grant select on assignments,assignment_learners to authenticated;
revoke truncate on assignments,assignment_learners,assignment_write_receipts from public,anon,authenticated;

create function public.manage_assignment(
  p_action text,p_assignment uuid,p_class uuid,p_expected_revision integer,p_request uuid,p_content jsonb
) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare
  v_actor uuid:=auth.uid(); v_role text; v_center uuid; v_class_center uuid;
  v_assignment assignments%rowtype; v_link class_course_assignments%rowtype;
  v_receipt assignment_write_receipts%rowtype; v_payload jsonb; v_result jsonb;
  v_lesson course_lessons%rowtype; v_title text; v_objective text; v_due timestamptz; v_lesson_id uuid;
begin
  select role,center_id into v_role,v_center from users where id=v_actor;
  if v_actor is null or v_role is null or v_role not in ('teacher','admin') then
    raise exception 'Not authorized' using errcode='42501';
  end if;
  if p_action is null or p_action not in ('create','edit','publish','archive') or p_assignment is null or p_request is null or p_expected_revision is null or p_expected_revision<0 then
    raise exception 'Invalid request' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('assignment-request:'||v_actor::text||':'||p_request::text,0));
  if p_action='create' then
    if p_class is null or p_expected_revision<>0 or p_content is null or jsonb_typeof(p_content)<>'object' then
      raise exception 'Invalid assignment' using errcode='22023'; end if;
    perform pg_advisory_xact_lock(hashtextextended('assignment-class:'||p_class::text,0));
    select center_id into v_class_center from classes where id=p_class for update;
    if v_class_center is null or not public.can_manage_class(p_class) then raise exception 'Not authorized' using errcode='42501'; end if;

  else
    perform pg_advisory_xact_lock(hashtextextended('assignment:'||p_assignment::text,0));
    select * into v_assignment from assignments where id=p_assignment for update;
    if v_assignment.id is null or not public.can_manage_class(v_assignment.class_id) then raise exception 'Not authorized' using errcode='42501'; end if;
    if p_class is not null and p_class<>v_assignment.class_id then raise exception 'Invalid class' using errcode='22023'; end if;
  end if;
  v_payload:=jsonb_build_object('action',p_action,'assignment',p_assignment,'class',p_class,'revision',p_expected_revision,'content',p_content);
  select * into v_receipt from assignment_write_receipts where actor_id=v_actor and request_id=p_request;
  if found then
    if v_receipt.payload<>v_payload then raise exception 'Request reused' using errcode='P0002'; end if;
    return v_receipt.result;
  end if;
  if p_action='create' then
    select * into v_link from class_course_assignments where class_id=p_class and ended_at is null for update;
    if v_link.id is null then raise exception 'No active course' using errcode='P0002'; end if;
    perform pg_advisory_xact_lock(hashtextextended('assignment:'||p_assignment::text,0));
    if exists(select 1 from assignments where id=p_assignment) then raise exception 'Assignment already exists' using errcode='P0002'; end if;
  elsif p_action in ('edit','publish') then
    perform 1 from class_course_assignments where id=v_assignment.course_assignment_id and ended_at is null for share;
    if not found then raise exception 'Class course changed' using errcode='P0002'; end if;
  end if;
  if p_action in ('create','edit') then
    if p_content is null or jsonb_typeof(p_content)<>'object' then raise exception 'Invalid content' using errcode='22023'; end if;
    if jsonb_typeof(p_content->'title') is distinct from 'string' or jsonb_typeof(p_content->'brief') is distinct from 'string'
      or not (p_content ? 'dueAt') or not (p_content ? 'courseLessonId') or exists(select 1 from jsonb_object_keys(p_content) k where k not in ('title','brief','dueAt','courseLessonId'))
      or (p_content ? 'dueAt' and jsonb_typeof(p_content->'dueAt') not in ('string','null'))
      or jsonb_typeof(p_content->'courseLessonId') not in ('string','null') then
      raise exception 'Invalid content' using errcode='22023';
    end if;
    if length(btrim(p_content->>'title')) not between 1 and 200 or length(p_content->>'brief')>20000 then
      raise exception 'Invalid content' using errcode='22023';
    end if;
    v_lesson_id:=nullif(p_content->>'courseLessonId','')::uuid;
    if p_content->>'dueAt' is not null then v_due:=(p_content->>'dueAt')::timestamptz; else v_due:=null; end if;
    if p_action='create' then
      if v_lesson_id is not null then
        perform 1 from course_lessons where id=v_lesson_id and course_id=v_link.course_id and archived_at is null for share;
        if not found then raise exception 'Course lesson unavailable' using errcode='22023'; end if;
      end if;
      insert into assignments(id,class_id,center_id,course_assignment_id,course_id,course_lesson_id,title,brief,due_at,created_by,updated_by)
        values(p_assignment,p_class,v_link.center_id,v_link.id,v_link.course_id,v_lesson_id,p_content->>'title',p_content->>'brief',v_due,v_actor,v_actor);
      v_result:=jsonb_build_object('id',p_assignment,'revision',1,'status','draft');
    else
      if v_assignment.status<>'draft' then raise exception 'Published assignment is immutable' using errcode='P0002'; end if;
      if v_assignment.revision<>p_expected_revision then raise exception 'Stale revision' using errcode='P0002'; end if;
      if not exists(select 1 from class_course_assignments ca where ca.id=v_assignment.course_assignment_id and ca.ended_at is null) then
        raise exception 'Class course changed' using errcode='P0002'; end if;
      if v_lesson_id is not null then
        perform 1 from course_lessons where id=v_lesson_id and course_id=v_assignment.course_id and archived_at is null for share;
        if not found then raise exception 'Course lesson unavailable' using errcode='22023'; end if;
      end if;
      update assignments set course_lesson_id=v_lesson_id,title=p_content->>'title',brief=p_content->>'brief',due_at=v_due,
        revision=revision+1,updated_by=v_actor,updated_at=now() where id=p_assignment returning * into v_assignment;
      v_result:=jsonb_build_object('id',p_assignment,'revision',v_assignment.revision,'status',v_assignment.status);
    end if;
  elsif p_action='publish' then
    if p_content is not null then raise exception 'Invalid content' using errcode='22023'; end if;
    if v_assignment.status<>'draft' or v_assignment.revision<>p_expected_revision then raise exception 'Stale or non-draft assignment' using errcode='P0002'; end if;
    if not exists(select 1 from class_course_assignments ca where ca.id=v_assignment.course_assignment_id and ca.ended_at is null) then
      raise exception 'Class course changed' using errcode='P0002'; end if;
    if v_assignment.course_lesson_id is not null then
      select * into v_lesson from course_lessons where id=v_assignment.course_lesson_id and course_id=v_assignment.course_id and archived_at is null for share;
      if v_lesson.id is null then raise exception 'Course lesson unavailable' using errcode='P0002'; end if;
      v_title:=v_lesson.title; v_objective:=v_lesson.objective;
    end if;
    update assignments set status='published',published_at=now(),lesson_title_snapshot=v_title,
      lesson_objective_snapshot=v_objective,revision=revision+1,updated_by=v_actor,updated_at=now()
      where id=p_assignment returning * into v_assignment;
    insert into assignment_learners(assignment_id,class_id,center_id,student_id)
      select p_assignment,e.class_id,c.center_id,s.id from enrollments e join classes c on c.id=e.class_id
      join students s on s.id=e.student_id and s.center_id=c.center_id
      where e.class_id=v_assignment.class_id on conflict(assignment_id,student_id) do nothing;
    v_result:=jsonb_build_object('id',p_assignment,'revision',v_assignment.revision,'status','published',
      'learnerCount',(select count(*) from assignment_learners where assignment_id=p_assignment));
  else
    if p_content is not null then raise exception 'Invalid content' using errcode='22023'; end if;
    if v_assignment.status='archived' or v_assignment.revision<>p_expected_revision then raise exception 'Stale assignment' using errcode='P0002'; end if;
    update assignments set status='archived',revision=revision+1,updated_by=v_actor,updated_at=now()
      where id=p_assignment returning * into v_assignment;
    update assignment_learners set submission_open=false where assignment_id=p_assignment;
    v_result:=jsonb_build_object('id',p_assignment,'revision',v_assignment.revision,'status','archived');
  end if;
  insert into assignment_write_receipts(actor_id,request_id,payload,result) values(v_actor,p_request,v_payload,v_result);
  return v_result;
end;
$$;
revoke all on function public.manage_assignment(text,uuid,uuid,integer,uuid,jsonb) from public,anon;
grant execute on function public.manage_assignment(text,uuid,uuid,integer,uuid,jsonb) to authenticated;
commit;

-- Versioned learner submissions and review history (forward migration).
begin;

-- ASCII/punycode hostnames, optional valid TCP port, no credentials or backslashes.
create function public.valid_submission_url(p_url text) returns boolean
language sql immutable set search_path=public,pg_temp as $$
  select coalesce(length(p_url) between 1 and 2048
    and p_url !~ '[[:space:]]'
    and p_url ~ '^https://[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?(:[0-9]{1,5})?([/?#][^[:space:]\\]*)?$'
    and coalesce(substring(p_url from '^https://[^/?#:]+:([0-9]+)')::integer between 1 and 65535,true),false)
$$;

create table submission_threads (
  id uuid primary key default gen_random_uuid(),
  assignment_id uuid not null,
  student_id uuid not null,
  next_version integer not null default 1 check (next_version > 0),
  unique (assignment_id,student_id),
  foreign key (assignment_id,student_id) references assignment_learners(assignment_id,student_id)
);
create table submission_versions (
  id uuid primary key default gen_random_uuid(),
  thread_id uuid not null references submission_threads(id),
  version integer not null check (version > 0),
  project_url text not null check (public.valid_submission_url(project_url)),
  reflection text not null check (length(btrim(reflection,E' \t\r\n')) between 1 and 10000),
  submitted_by uuid not null references users(id),
  submitted_role text not null check (submitted_role in ('parent','teacher','admin')),
  submitted_at timestamptz not null default clock_timestamp(),
  is_late boolean not null,
  request_id uuid not null,
  unique (thread_id,version),
  unique (submitted_by,request_id)
);
create table submission_reviews (
  id uuid primary key default gen_random_uuid(),
  submission_id uuid not null references submission_versions(id),
  sequence integer not null check (sequence > 0),
  outcome text not null check (outcome in ('revision','approved')),
  feedback text not null check (length(btrim(feedback,E' \t\r\n')) between 1 and 10000),
  reviewed_by uuid not null references users(id),
  reviewed_at timestamptz not null default clock_timestamp(),
  supersedes_id uuid,
  request_id uuid not null,
  unique (submission_id,sequence),
  unique (id,submission_id),
  foreign key (supersedes_id,submission_id) references submission_reviews(id,submission_id),
  unique (reviewed_by,request_id)
);
create table submission_write_receipts (
  actor_id uuid not null references users(id),
  request_id uuid not null,
  payload jsonb not null,
  result jsonb not null,
  primary key (actor_id,request_id)
);

create function public.can_read_submission_thread(p_thread uuid) returns boolean
language sql stable security definer set search_path=public,pg_temp as $$
  select exists(select 1 from submission_threads t join assignments a on a.id=t.assignment_id
    where t.id=p_thread and (public.can_manage_class(a.class_id)
      or public.can_read_assignment(a.id,t.student_id)))
$$;
alter table submission_threads enable row level security;
alter table submission_versions enable row level security;
alter table submission_reviews enable row level security;
alter table submission_write_receipts enable row level security;
create policy "submission_threads_read" on submission_threads for select to authenticated
  using(public.can_read_submission_thread(id));
create policy "submission_versions_read" on submission_versions for select to authenticated
  using(public.can_read_submission_thread(thread_id));
create policy "submission_reviews_read" on submission_reviews for select to authenticated
  using(exists(select 1 from submission_versions v where v.id=submission_id));
create policy "submission_receipts_private" on submission_write_receipts for select to authenticated using(false);
grant select on submission_threads,submission_versions,submission_reviews to authenticated;
revoke truncate on submission_threads,submission_versions,submission_reviews,submission_write_receipts from public,anon,authenticated;

-- Re-enrollment does not silently reopen previously closed learner snapshots.
create function public.close_removed_learner_submissions() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
begin
  if tg_op='DELETE' or old.class_id is distinct from new.class_id or old.student_id is distinct from new.student_id then
    update assignment_learners set submission_open=false
      where class_id=old.class_id and student_id=old.student_id and submission_open;
  end if;
  return null;
end;
$$;
create trigger enrollment_closes_submissions after delete or update of class_id,student_id on enrollments
  for each row execute function public.close_removed_learner_submissions();

-- Close already-unenrolled snapshots at migration cutover too.
update assignment_learners al set submission_open=false
  where al.submission_open and not exists(select 1 from enrollments e
    where e.class_id=al.class_id and e.student_id=al.student_id);

create function public.submit_assignment(
  p_assignment uuid,p_student uuid,p_request uuid,p_url text,p_reflection text
) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare
  v_actor uuid:=auth.uid(); v_role text; v_assignment assignments%rowtype;
  v_thread submission_threads%rowtype; v_learner assignment_learners%rowtype;
  v_receipt submission_write_receipts%rowtype; v_payload jsonb; v_result jsonb;
  v_id uuid; v_time timestamptz;
begin
  select role into v_role from users where id=v_actor;
  if v_actor is null or v_role is null or v_role not in ('parent','teacher','admin') then
    raise exception 'Not authorized' using errcode='42501'; end if;
  if p_assignment is null or p_student is null or p_request is null or not public.valid_submission_url(p_url)
    or p_reflection is null or length(btrim(p_reflection,E' \t\r\n')) not between 1 and 10000 then
    raise exception 'Invalid submission' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('submission-request:'||v_actor::text||':'||p_request::text,0));
  select * into v_assignment from assignments where id=p_assignment for share;
  if v_assignment.id is null or not (public.can_manage_class(v_assignment.class_id)
    or public.can_read_assignment(p_assignment,p_student)) then
    raise exception 'Not authorized' using errcode='42501'; end if;
  if not exists(select 1 from assignment_learners where assignment_id=p_assignment and student_id=p_student) then
    raise exception 'Learner unavailable' using errcode='42501'; end if;
  v_payload:=jsonb_build_object('action','submit','assignment',p_assignment,'student',p_student,'url',p_url,'reflection',p_reflection);
  select * into v_receipt from submission_write_receipts where actor_id=v_actor and request_id=p_request;
  if found then
    if v_receipt.payload<>v_payload then raise exception 'Request reused' using errcode='P0002'; end if;
    return v_receipt.result;
  end if;
  if v_assignment.status<>'published' then raise exception 'Assignment closed' using errcode='P0002'; end if;
  -- Lock enrollment before learner, matching the deletion trigger's lock order.
  perform 1 from enrollments where class_id=v_assignment.class_id and student_id=p_student for share;
  if not found then raise exception 'Learner no longer enrolled' using errcode='P0002'; end if;
  select * into v_learner from assignment_learners where assignment_id=p_assignment and student_id=p_student for update;
  if not v_learner.submission_open then raise exception 'Submissions closed' using errcode='P0002'; end if;
  insert into submission_threads(assignment_id,student_id) values(p_assignment,p_student)
    on conflict(assignment_id,student_id) do nothing;
  select * into v_thread from submission_threads where assignment_id=p_assignment and student_id=p_student for update;
  v_time:=clock_timestamp();
  insert into submission_versions(thread_id,version,project_url,reflection,submitted_by,submitted_role,submitted_at,is_late,request_id)
    values(v_thread.id,v_thread.next_version,p_url,p_reflection,v_actor,v_role,v_time,
      coalesce(v_time>v_assignment.due_at,false),p_request) returning id into v_id;
  update submission_threads set next_version=next_version+1 where id=v_thread.id;
  v_result:=jsonb_build_object('id',v_id,'threadId',v_thread.id,'version',v_thread.next_version,
    'status','submitted','isLate',coalesce(v_time>v_assignment.due_at,false));
  insert into submission_write_receipts values(v_actor,p_request,v_payload,v_result);
  return v_result;
end;
$$;

create function public.review_submission(
  p_submission uuid,p_expected_version integer,p_expected_review uuid,
  p_request uuid,p_outcome text,p_feedback text
) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare
  v_actor uuid:=auth.uid(); v_role text; v_version submission_versions%rowtype;
  v_thread submission_threads%rowtype; v_assignment assignments%rowtype;
  v_review submission_reviews%rowtype; v_receipt submission_write_receipts%rowtype;
  v_payload jsonb; v_result jsonb; v_id uuid;
begin
  select role into v_role from users where id=v_actor;
  if v_actor is null or v_role is null or v_role not in ('teacher','admin') then
    raise exception 'Not authorized' using errcode='42501'; end if;
  if p_submission is null or p_request is null or p_expected_version is null or p_expected_version<1
    or p_outcome is null or p_outcome not in ('revision','approved')
    or p_feedback is null or length(btrim(p_feedback,E' \t\r\n')) not between 1 and 10000 then
    raise exception 'Invalid review' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('submission-request:'||v_actor::text||':'||p_request::text,0));
  select * into v_version from submission_versions where id=p_submission;
  select * into v_thread from submission_threads where id=v_version.thread_id;
  select * into v_assignment from assignments where id=v_thread.assignment_id for share;
  if v_assignment.id is null or not public.can_manage_class(v_assignment.class_id) then
    raise exception 'Not authorized' using errcode='42501'; end if;
  v_payload:=jsonb_build_object('action','review','submission',p_submission,'version',p_expected_version,
    'previousReview',p_expected_review,'outcome',p_outcome,'feedback',p_feedback);
  select * into v_receipt from submission_write_receipts where actor_id=v_actor and request_id=p_request;
  if found then
    if v_receipt.payload<>v_payload then raise exception 'Request reused' using errcode='P0002'; end if;
    return v_receipt.result;
  end if;
  if v_assignment.status<>'published' then raise exception 'Assignment closed' using errcode='P0002'; end if;
  select * into v_thread from submission_threads where id=v_version.thread_id for update;
  if v_version.version<>p_expected_version or v_thread.next_version-1<>p_expected_version then
    raise exception 'Newer submission exists' using errcode='P0002'; end if;
  select * into v_review from submission_reviews where submission_id=p_submission order by sequence desc limit 1;
  if v_review.id is distinct from p_expected_review then raise exception 'Review changed' using errcode='P0002'; end if;
  insert into submission_reviews(submission_id,sequence,outcome,feedback,reviewed_by,supersedes_id,request_id)
    values(p_submission,coalesce(v_review.sequence,0)+1,p_outcome,p_feedback,v_actor,v_review.id,p_request) returning id into v_id;
  v_result:=jsonb_build_object('id',v_id,'submissionId',p_submission,'sequence',coalesce(v_review.sequence,0)+1,'status',p_outcome);
  insert into submission_write_receipts values(v_actor,p_request,v_payload,v_result);
  return v_result;
end;
$$;

revoke all on function public.can_read_submission_thread(uuid),public.close_removed_learner_submissions(),
  public.submit_assignment(uuid,uuid,uuid,text,text),public.review_submission(uuid,integer,uuid,uuid,text,text) from public,anon;
revoke all on function public.close_removed_learner_submissions() from authenticated;
grant execute on function public.can_read_submission_thread(uuid),
  public.submit_assignment(uuid,uuid,uuid,text,text),public.review_submission(uuid,integer,uuid,uuid,text,text) to authenticated;
commit;

-- Explicit assignment roster changes (forward migration).
begin;

alter table assignment_learners add column revision integer not null default 1 check (revision > 0);

-- Automatic enrollment closure and assignment archive must invalidate stale edits too.
create function public.bump_assignment_learner_revision() returns trigger
language plpgsql set search_path=public,pg_temp as $$
begin
  if new.submission_open is distinct from old.submission_open then
    new.revision:=old.revision+1;
  end if;
  return new;
end;
$$;
create trigger assignment_learner_revision before update on assignment_learners
  for each row execute function public.bump_assignment_learner_revision();
revoke all on function public.bump_assignment_learner_revision() from public,anon,authenticated;

create function public.set_assignment_learner(
  p_assignment uuid,p_student uuid,p_open boolean,p_expected_revision integer,p_request uuid
) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare
  v_actor uuid:=auth.uid(); v_assignment assignments%rowtype;
  v_learner assignment_learners%rowtype; v_receipt assignment_write_receipts%rowtype;
  v_payload jsonb; v_result jsonb; v_enrolled boolean;
begin
  if v_actor is null then raise exception 'Not authorized' using errcode='42501'; end if;
  if p_assignment is null or p_student is null or p_open is null or p_request is null
    or p_expected_revision is null or p_expected_revision<0 then
    raise exception 'Invalid roster request' using errcode='22023'; end if;
  -- Share the assignment receipt namespace and retry lock with other assignment writes.
  perform pg_advisory_xact_lock(hashtextextended('assignment-request:'||v_actor::text||':'||p_request::text,0));
  select * into v_assignment from assignments where id=p_assignment for share;
  if v_assignment.id is null or not public.can_manage_class(v_assignment.class_id) then
    raise exception 'Not authorized' using errcode='42501'; end if;
  v_payload:=jsonb_build_object('action','roster','assignment',p_assignment,'student',p_student,
    'open',p_open,'revision',p_expected_revision);
  select * into v_receipt from assignment_write_receipts where actor_id=v_actor and request_id=p_request;
  if found then
    if v_receipt.payload<>v_payload then raise exception 'Request reused' using errcode='P0002'; end if;
    return v_receipt.result;
  end if;
  if v_assignment.status<>'published' then raise exception 'Assignment not published' using errcode='P0002'; end if;
  -- Same order as submission and enrollment deletion: enrollment, then learner.
  perform 1 from enrollments where class_id=v_assignment.class_id and student_id=p_student for share;
  v_enrolled:=found;
  if p_open and not v_enrolled then raise exception 'Learner not enrolled' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('assignment-learner:'||p_assignment::text||':'||p_student::text,0));
  select * into v_learner from assignment_learners where assignment_id=p_assignment and student_id=p_student for update;
  if not found then
    if not p_open or p_expected_revision<>0 then raise exception 'Learner changed' using errcode='P0002'; end if;
    -- Enrollment alone does not establish center consistency in legacy data.
    perform 1 from students where id=p_student and center_id=v_assignment.center_id for share;
    if not found then raise exception 'Learner unavailable' using errcode='22023'; end if;
    insert into assignment_learners(assignment_id,class_id,center_id,student_id)
      values(p_assignment,v_assignment.class_id,v_assignment.center_id,p_student) returning * into v_learner;
  else
    if v_learner.revision<>p_expected_revision then raise exception 'Learner changed' using errcode='P0002'; end if;
    update assignment_learners set submission_open=p_open
      where assignment_id=p_assignment and student_id=p_student returning * into v_learner;
  end if;
  v_result:=jsonb_build_object('assignmentId',p_assignment,'studentId',p_student,
    'submissionOpen',v_learner.submission_open,'revision',v_learner.revision);
  insert into assignment_write_receipts(actor_id,request_id,payload,result) values(v_actor,p_request,v_payload,v_result);
  return v_result;
end;
$$;
revoke all on function public.set_assignment_learner(uuid,uuid,boolean,integer,uuid) from public,anon;
grant execute on function public.set_assignment_learner(uuid,uuid,boolean,integer,uuid) to authenticated;
commit;

-- General feedback publication boundary (forward migration).
begin;

alter table lessons add constraint lessons_id_class_unique unique(id,class_id);
create table student_feedback (
  id uuid primary key,
  student_id uuid not null,
  class_id uuid not null,
  center_id uuid not null,
  lesson_id uuid,
  title text not null check(length(btrim(title)) between 1 and 200),
  strengths text not null check(length(btrim(strengths,E' \t\r\n')) between 1 and 10000),
  next_steps text not null check(length(btrim(next_steps,E' \t\r\n')) between 1 and 10000),
  rating text not null check(rating in ('Getting started','Growing','Confident','Independent')),
  revision integer not null default 1 check(revision>0),
  created_by uuid not null references users(id),
  updated_by uuid not null references users(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key(student_id,center_id) references students(id,center_id),
  foreign key(class_id,center_id) references classes(id,center_id),
  foreign key(lesson_id,class_id) references lessons(id,class_id),
  unique(id,student_id,class_id,center_id)
);
create index student_feedback_student_idx on student_feedback(student_id,id);
create table published_feedback (
  id uuid primary key default gen_random_uuid(),
  feedback_id uuid not null,
  student_id uuid not null,
  class_id uuid not null,
  center_id uuid not null,
  draft_revision integer not null check(draft_revision>0),
  title text not null check(length(btrim(title)) between 1 and 200),
  strengths text not null check(length(btrim(strengths,E' \t\r\n')) between 1 and 10000),
  next_steps text not null check(length(btrim(next_steps,E' \t\r\n')) between 1 and 10000),
  rating text not null check(rating in ('Getting started','Growing','Confident','Independent')),
  published_by uuid not null references users(id),
  published_at timestamptz not null default now(),
  withdrawn_by uuid references users(id),
  withdrawn_at timestamptz,
  foreign key(feedback_id,student_id,class_id,center_id) references student_feedback(id,student_id,class_id,center_id),
  unique(feedback_id,draft_revision),
  check((withdrawn_at is null)=(withdrawn_by is null))
);
create index published_feedback_student_idx on published_feedback(student_id,id);
create table feedback_write_receipts (
  actor_id uuid not null references users(id),request_id uuid not null,
  payload jsonb not null,result jsonb not null,created_at timestamptz not null default now(),
  primary key(actor_id,request_id)
);
alter table student_feedback enable row level security;
alter table published_feedback enable row level security;
alter table feedback_write_receipts enable row level security;
create policy "feedback_drafts_staff" on student_feedback for select to authenticated
  using(public.can_manage_class(class_id));
create policy "feedback_publications_scoped" on published_feedback for select to authenticated
  using(public.can_manage_class(class_id) or (withdrawn_at is null and exists(
    select 1 from student_guardians sg join users u on u.id=sg.guardian_id
    where sg.student_id=published_feedback.student_id and u.id=auth.uid() and u.role='parent')));
create policy "feedback_receipts_private" on feedback_write_receipts for select to authenticated using(false);
grant select on student_feedback,published_feedback to authenticated;
revoke truncate on student_feedback,published_feedback,feedback_write_receipts from public,anon,authenticated;

create function public.manage_feedback(
  p_action text,p_id uuid,p_student uuid,p_class uuid,p_expected_revision integer,p_request uuid,p_content jsonb
) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare
  v_actor uuid:=auth.uid(); v_draft student_feedback%rowtype;
  v_publication published_feedback%rowtype; v_receipt feedback_write_receipts%rowtype;
  v_center uuid; v_lesson uuid; v_payload jsonb; v_result jsonb;
begin
  if v_actor is null or not exists(select 1 from users where id=v_actor and role in ('teacher','admin')) then
    raise exception 'Not authorized' using errcode='42501'; end if;
  if p_action is null or p_action not in ('create','edit','publish','withdraw') or p_id is null or p_request is null
    or p_expected_revision is null or p_expected_revision<0 then raise exception 'Invalid request' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('feedback-request:'||v_actor::text||':'||p_request::text,0));
  if p_action='create' then
    if p_student is null or p_class is null or p_expected_revision<>0 then raise exception 'Invalid feedback' using errcode='22023'; end if;
    if not public.can_manage_class(p_class) then raise exception 'Not authorized' using errcode='42501'; end if;
    perform pg_advisory_xact_lock(hashtextextended('feedback:'||p_id::text,0));
  else
    if p_student is not null or p_class is not null then raise exception 'Invalid scope' using errcode='22023'; end if;
    if p_action='withdraw' then
      select * into v_publication from published_feedback where id=p_id;
      select * into v_draft from student_feedback where id=v_publication.feedback_id for update;
    else
      select * into v_draft from student_feedback where id=p_id for update;
    end if;
    if v_draft.id is null or not public.can_manage_class(v_draft.class_id) then
      raise exception 'Not authorized' using errcode='42501'; end if;
  end if;
  v_payload:=jsonb_build_object('action',p_action,'id',p_id,'student',p_student,'class',p_class,
    'revision',p_expected_revision,'content',p_content);
  select * into v_receipt from feedback_write_receipts where actor_id=v_actor and request_id=p_request;
  if found then
    if v_receipt.payload<>v_payload then raise exception 'Request reused' using errcode='P0002'; end if;
    return v_receipt.result;
  end if;
  if p_action in ('create','edit') then
    if p_content is null or jsonb_typeof(p_content)<>'object' then raise exception 'Invalid content' using errcode='22023'; end if;
    if jsonb_typeof(p_content->'title') is distinct from 'string'
      or jsonb_typeof(p_content->'strengths') is distinct from 'string'
      or jsonb_typeof(p_content->'nextSteps') is distinct from 'string'
      or jsonb_typeof(p_content->'rating') is distinct from 'string'
      or not(p_content ? 'lessonId') or jsonb_typeof(p_content->'lessonId') not in ('null','string')
      or exists(select 1 from jsonb_object_keys(p_content) k where k not in ('title','strengths','nextSteps','rating','lessonId')) then
      raise exception 'Invalid content' using errcode='22023'; end if;
    v_lesson:=(p_content->>'lessonId')::uuid;
    if p_action='create' then
      if exists(select 1 from student_feedback where id=p_id) then raise exception 'Feedback exists' using errcode='P0002'; end if;
      select center_id into v_center from classes where id=p_class;
      perform 1 from enrollments where class_id=p_class and student_id=p_student for share;
      if not found then raise exception 'Learner not enrolled' using errcode='22023'; end if;
      insert into student_feedback(id,student_id,class_id,center_id,lesson_id,title,strengths,next_steps,rating,created_by,updated_by)
        values(p_id,p_student,p_class,v_center,v_lesson,p_content->>'title',p_content->>'strengths',p_content->>'nextSteps',p_content->>'rating',v_actor,v_actor)
        returning * into v_draft;
    else
      if v_draft.revision<>p_expected_revision then raise exception 'Stale draft' using errcode='P0002'; end if;
      update student_feedback set lesson_id=v_lesson,title=p_content->>'title',strengths=p_content->>'strengths',
        next_steps=p_content->>'nextSteps',rating=p_content->>'rating',revision=revision+1,updated_by=v_actor,updated_at=now()
        where id=p_id returning * into v_draft;
    end if;
    v_result:=jsonb_build_object('id',v_draft.id,'revision',v_draft.revision);
  else
    if p_content is not null then raise exception 'Invalid content' using errcode='22023'; end if;
    if p_action='publish' then
      if v_draft.revision<>p_expected_revision then raise exception 'Stale draft' using errcode='P0002'; end if;
      if exists(select 1 from published_feedback where feedback_id=p_id and draft_revision=p_expected_revision) then
        raise exception 'Revision already published' using errcode='P0002'; end if;
      insert into published_feedback(feedback_id,student_id,class_id,center_id,draft_revision,title,strengths,next_steps,rating,published_by)
        values(v_draft.id,v_draft.student_id,v_draft.class_id,v_draft.center_id,v_draft.revision,v_draft.title,v_draft.strengths,v_draft.next_steps,v_draft.rating,v_actor)
        returning * into v_publication;
    else
      if v_publication.draft_revision<>p_expected_revision then raise exception 'Wrong publication revision' using errcode='P0002'; end if;
      update published_feedback set withdrawn_at=coalesce(withdrawn_at,now()),withdrawn_by=coalesce(withdrawn_by,v_actor)
        where id=p_id returning * into v_publication;
    end if;
    v_result:=jsonb_build_object('id',v_publication.id,'feedbackId',v_publication.feedback_id,
      'draftRevision',v_publication.draft_revision,'withdrawn',v_publication.withdrawn_at is not null);
  end if;
  insert into feedback_write_receipts(actor_id,request_id,payload,result) values(v_actor,p_request,v_payload,v_result);
  return v_result;
end;
$$;
revoke all on function public.manage_feedback(text,uuid,uuid,uuid,integer,uuid,jsonb) from public,anon;
grant execute on function public.manage_feedback(text,uuid,uuid,uuid,integer,uuid,jsonb) to authenticated;
commit;

-- Independent staff-configurable module target, separate from detailed lesson plans.
alter function public.save_course_content(uuid,uuid,integer,uuid,jsonb) rename to save_course_content_v1;
revoke all on function public.save_course_content_v1(uuid,uuid,integer,uuid,jsonb) from public,anon,authenticated;
create function public.save_course_content(
  p_course uuid, p_lesson uuid, p_expected_revision integer,
  p_request uuid, p_content jsonb
) returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_actor uuid := auth.uid();
  v_role text;
  v_center uuid;
  v_course courses%rowtype;
  v_receipt course_target_write_receipts%rowtype;
  v_payload jsonb;
  v_content jsonb;
  v_result jsonb;
  v_count integer;
begin
  if p_lesson is not null then
    return public.save_course_content_v1(p_course,p_lesson,p_expected_revision,p_request,p_content);
  end if;
  if p_content is null or jsonb_typeof(p_content) <> 'object'
     or jsonb_typeof(p_content->'lesson_count') is distinct from 'number'
     or (p_content->>'lesson_count') !~ '^[0-9]{1,5}$' then
    raise exception 'Invalid lesson count' using errcode='22023';
  end if;
  v_count := (p_content->>'lesson_count')::integer;
  if v_count < 0 or v_count > 10000 then
    raise exception 'Invalid lesson count' using errcode='22023';
  end if;
  select role,center_id into v_role,v_center from users where id=v_actor;
  if v_actor is null or v_center is null or v_role not in ('teacher','admin') then
    raise exception 'Not authorized' using errcode='42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('course-request:'||v_actor::text||':'||p_request::text,0));
  perform pg_advisory_xact_lock(hashtextextended('course:'||p_course::text,0));
  select * into v_course from courses where id=p_course for update;
  if v_course.id is not null and (v_course.center_id<>v_center or (v_role<>'admin' and v_course.owner_id<>v_actor)) then
    raise exception 'Not authorized' using errcode='42501';
  end if;
  v_payload:=jsonb_build_object('course',p_course,'lesson',p_lesson,'revision',p_expected_revision,'content',p_content);
  select * into v_receipt from course_target_write_receipts where actor_id=v_actor and request_id=p_request;
  if found then
    if v_receipt.payload<>v_payload then raise exception 'Request reused' using errcode='P0002'; end if;
    return v_receipt.result;
  end if;
  v_content:=p_content-'lesson_count';
  v_result:=public.save_course_content_v1(p_course,null,p_expected_revision,p_request,v_content);
  update courses set lesson_count=v_count where id=p_course;
  insert into course_target_write_receipts(actor_id,request_id,payload,result)
    values(v_actor,p_request,v_payload,v_result);
  return v_result;
end;
$$;
revoke all on function public.save_course_content(uuid,uuid,integer,uuid,jsonb) from public,anon;
grant execute on function public.save_course_content(uuid,uuid,integer,uuid,jsonb) to authenticated;

-- Course curriculum mapping (also supplied as a forward migration).
begin;

alter table lessons add column course_id uuid;
alter table lessons add column course_lesson_id uuid;
alter table lessons add constraint lessons_course_mapping_pair
  check ((course_id is null) = (course_lesson_id is null));
alter table lessons add constraint lessons_course_mapping_source_fk
  foreign key (course_lesson_id,course_id) references course_lessons(id,course_id);
create unique index lessons_course_mapping_once
  on lessons(class_id,course_id,course_lesson_id) where course_lesson_id is not null;

create table course_curriculum_write_receipts (
  actor_id uuid not null references users(id),
  request_id uuid not null,
  payload jsonb not null,
  result jsonb not null,
  created_at timestamptz not null default now(),
  primary key (actor_id,request_id)
);
alter table course_curriculum_write_receipts enable row level security;
create policy "course_curriculum_receipts_private" on course_curriculum_write_receipts
  for select to authenticated using (false);
revoke all on course_curriculum_write_receipts from public,anon,authenticated;
revoke truncate on course_curriculum_write_receipts from public,anon,authenticated;

create function public.enforce_class_course_lesson_mapping()
returns trigger language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if new.course_id is null and new.course_lesson_id is null then return new; end if;
  if new.course_id is null or new.course_lesson_id is null then
    raise exception 'Incomplete course lesson mapping' using errcode='23514';
  end if;
  if tg_op='UPDATE' and old.course_id is not distinct from new.course_id
     and old.course_lesson_id is not distinct from new.course_lesson_id then return new; end if;
  if not exists (
    select 1 from class_course_assignments ca
    join course_lessons cl on cl.course_id=ca.course_id
    where ca.class_id=new.class_id and ca.course_id=new.course_id and ca.ended_at is null
      and cl.id=new.course_lesson_id and cl.archived_at is null
  ) then raise exception 'Mapping requires a lesson from the active class course' using errcode='23514'; end if;
  return new;
end;
$$;
create trigger lessons_course_mapping_guard
  before insert or update of course_id,course_lesson_id on lessons
  for each row execute function public.enforce_class_course_lesson_mapping();
revoke all on function public.enforce_class_course_lesson_mapping() from public,anon,authenticated;

create function public.map_class_course_lessons(
  p_class uuid,p_course uuid,p_request uuid,p_mappings jsonb
) returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_actor uuid:=auth.uid();
  v_role text;
  v_user_center uuid;
  v_center uuid;
  v_teacher uuid;
  v_active class_course_assignments%rowtype;
  v_receipt course_curriculum_write_receipts%rowtype;
  v_course_lesson course_lessons%rowtype;
  v_class_lesson lessons%rowtype;
  v_item jsonb;
  v_source uuid;
  v_target uuid;
  v_target_text text;
  v_sequence integer;
  v_payload jsonb;
  v_results jsonb:='[]'::jsonb;
  v_created integer:=0;
  v_mapped integer:=0;
  v_duplicates integer;
begin
  select role,center_id into v_role,v_user_center from users where id=v_actor;
  select center_id,teacher_id into v_center,v_teacher from classes where id=p_class for update;
  if v_actor is null or v_role not in ('teacher','admin') or v_center is null
     or v_user_center is distinct from v_center
     or (v_role='teacher' and v_teacher is distinct from v_actor) then
    raise exception 'Not authorized' using errcode='42501';
  end if;
  if p_course is null or p_request is null or jsonb_typeof(p_mappings) is distinct from 'array'
     or jsonb_array_length(p_mappings) not between 1 and 100 then
    raise exception 'Invalid curriculum mapping' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('class-curriculum-request:'||v_actor::text||':'||p_request::text,0));
  perform pg_advisory_xact_lock(hashtextextended('class-curriculum:'||p_class::text,0));
  select * into v_active from class_course_assignments
    where class_id=p_class and course_id=p_course and ended_at is null for update;
  if v_active.id is null then raise exception 'Course is not active for class' using errcode='42501'; end if;

  select count(*) into v_duplicates from (
    select value->>'courseLessonId' from jsonb_array_elements(p_mappings)
    group by value->>'courseLessonId' having count(*)>1
  ) d;
  if v_duplicates>0 or exists (
    select 1 from jsonb_array_elements(p_mappings) item
    where jsonb_typeof(item) is distinct from 'object'
       or jsonb_typeof(item->'courseLessonId') is distinct from 'string'
       or (jsonb_typeof(item->'lessonId') is distinct from 'string'
           and jsonb_typeof(item->'lessonId') is distinct from 'null')
  ) then raise exception 'Invalid or duplicate curriculum mapping' using errcode='22023'; end if;
  select count(*) into v_duplicates from (
    select value->>'lessonId' from jsonb_array_elements(p_mappings)
    where jsonb_typeof(value->'lessonId')='string'
    group by value->>'lessonId' having count(*)>1
  ) d;
  if v_duplicates>0 then raise exception 'A class lesson can only be mapped once per request' using errcode='22023'; end if;

  v_payload:=jsonb_build_object('class',p_class,'course',p_course,'mappings',p_mappings);
  select * into v_receipt from course_curriculum_write_receipts
    where actor_id=v_actor and request_id=p_request;
  if found then
    if v_receipt.payload<>v_payload then raise exception 'Request reused' using errcode='P0002'; end if;
    return v_receipt.result;
  end if;

  for v_item in select value from jsonb_array_elements(p_mappings) loop
    v_source:=(v_item->>'courseLessonId')::uuid;
    v_target_text:=v_item->>'lessonId';
    v_target:=case when v_target_text is null then null else v_target_text::uuid end;
    select * into v_course_lesson from course_lessons
      where id=v_source and course_id=p_course and archived_at is null for share;
    if v_course_lesson.id is null then raise exception 'Course lesson unavailable' using errcode='22023'; end if;

    select * into v_class_lesson from lessons
      where class_id=p_class and course_id=p_course and course_lesson_id=v_source for update;
    if v_class_lesson.id is not null then
      if v_target is not null and v_class_lesson.id<>v_target then
        raise exception 'Course lesson is already mapped' using errcode='P0002';
      end if;
    elsif v_target is not null then
      select * into v_class_lesson from lessons where id=v_target and class_id=p_class for update;
      if v_class_lesson.id is null or v_class_lesson.course_lesson_id is not null then
        raise exception 'Class lesson unavailable for mapping' using errcode='22023';
      end if;
      update lessons set course_id=p_course,course_lesson_id=v_source where id=v_target;
    else
      select coalesce(max(sequence_number),0)+1 into v_sequence from lessons where class_id=p_class;
      if v_sequence>10000 then raise exception 'Class lesson limit reached' using errcode='22023'; end if;
      insert into lessons(class_id,sequence_number,title,description,course_id,course_lesson_id)
        values(p_class,v_sequence,v_course_lesson.title,nullif(v_course_lesson.objective,''),p_course,v_source)
        returning * into v_class_lesson;
      v_created:=v_created+1;
    end if;
    v_mapped:=v_mapped+1;
    v_results:=v_results||jsonb_build_array(jsonb_build_object(
      'courseLessonId',v_source,'lessonId',v_class_lesson.id,
      'sequenceNumber',v_class_lesson.sequence_number
    ));
  end loop;

  v_payload:=jsonb_build_object('classId',p_class,'courseId',p_course,
    'mappedCount',v_mapped,'createdCount',v_created,'mappings',v_results);
  insert into course_curriculum_write_receipts(actor_id,request_id,payload,result)
    values(v_actor,p_request,jsonb_build_object('class',p_class,'course',p_course,'mappings',p_mappings),v_payload);
  return v_payload;
end;
$$;
revoke all on function public.map_class_course_lessons(uuid,uuid,uuid,jsonb) from public,anon;
grant execute on function public.map_class_course_lessons(uuid,uuid,uuid,jsonb) to authenticated;
revoke truncate on lessons from public,anon,authenticated;

commit;

